// Node.js 18+
const API_URL = "https://api.example.com/v1/charge";
const API_KEY = process.env.PAID_API_KEY;

if (!API_KEY) throw new Error("Missing PAID_API_KEY");

const MAX_ATTEMPTS = 3; // 1 initial attempt + at most 2 retries

function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function retryable(status: number) {
  return status === 408 || status === 429 || status >= 500;
}

async function callPaidApi(payload: unknown) {
  // Use an idempotency key when the operation can create a charge/order.
  const idempotencyKey = crypto.randomUUID();

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${API_KEY}`,
          "Content-Type": "application/json",
          "Idempotency-Key": idempotencyKey,
        },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(10_000),
      });

      if (response.ok) return await response.json();

      const body = await response.text();

      if (!retryable(response.status) || attempt === MAX_ATTEMPTS) {
        throw new Error(`API failed (${response.status}): ${body}`);
      }

      // Exponential backoff: 1s, then 2s.
      await sleep(1000 * 2 ** (attempt - 1));
    } catch (error) {
      if (attempt === MAX_ATTEMPTS) throw error;

      // Network/timeout errors may be transient; retry within the budget.
      await sleep(1000 * 2 ** (attempt - 1));
    }
  }

  throw new Error("Unreachable");
}

callPaidApi({ amount: 2500, currency: "usd" })
  .then(result => console.log(result))
  .catch(error => {
    console.error("Request failed:", error.message);
    process.exitCode = 1;
  });
```

**Retry budget:** the code makes **no more than three total attempts**: the first request plus up to two retries. It retries only likely-transient failures, waits between attempts, and then stops. For paid or non-idempotent operations, keep the same idempotency key so a retry does not accidentally create a duplicate charge.
